// Copies the ABI generated by `hardhat compile` into the backend and client so both use
// the real contract interface. Nothing here is hand-written.
const fs = require("fs");
const path = require("path");

const artifactPath = path.join(__dirname, "..", "artifacts", "contracts", "JeevanBinduRecords.sol", "JeevanBinduRecords.json");
if (!fs.existsSync(artifactPath)) {
  console.error("Artifact not found. Run `npm run compile` first.");
  process.exit(1);
}
const { abi } = JSON.parse(fs.readFileSync(artifactPath, "utf8"));
const targets = [
  path.join(__dirname, "..", "..", "server", "src", "blockchain", "JeevanBinduRecords.abi.json"),
];
for (const target of targets) {
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, JSON.stringify(abi, null, 2) + "\n");
  console.log("ABI written to", path.relative(process.cwd(), target));
}
